// Ring buffer for timestamp synchronization
public class TimestampRingBuffer {
    private static final int CAPACITY = 64;
    private final long[] timestamps = new long[CAPACITY];
    private final long[] sequenceNums = new long[CAPACITY];
    private int writeIndex = 0;

    public synchronized void write(long timestamp, long seqNum) {
        timestamps[writeIndex] = timestamp;
        sequenceNums[writeIndex] = seqNum;
        writeIndex = (writeIndex + 1) % CAPACITY;
    }

    public synchronized long[] readSince(long sinceSeqNum) {
        // Return timestamps for frames since the given sequence number
    }
}

// Android Keystore key protection
private KeyStore.KeyProtection getKeyProtection() {
    return new KeyStore.KeyProtection.Builder(
        KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
        .setUserAuthenticationRequired(true)
        .setUserAuthenticationParameters(0,
            KeyProperties.AUTH_BIOMETRIC_STRONG)
        .setInvalidatedByBiometricEnrollment(true)
        .build();
}
